const body = $input.first().json.body || $input.first().json;

// Touch message templates per touch number
const templates = {
  1: `Hi {{caller_name}}! Thanks for calling {{business_name}}. We'd love to help with {{service_interest}}. Reply here or call us back anytime!`,
  2: `Hi {{caller_name}}, just following up from {{business_name}}. Still interested in {{service_interest}}? We have availability this week — reply or call us!`,
  3: `{{caller_name}}, a quick note from {{business_name}} — our team is ready to help you with {{service_interest}}. Any questions I can answer?`,
  4: `Hi {{caller_name}}, last follow-up from {{business_name}}. When you're ready to move forward with {{service_interest}}, we're here. Reply anytime.`,
  5: `Final note from {{business_name}}: We're here whenever you're ready, {{caller_name}}. Take care and don't hesitate to reach out!`
};

const touch = body.touch_number || 1;
let message = templates[touch] || templates[1];

// Replace template variables
message = message
  .replace(/{{caller_name}}/g, body.caller_name || 'there')
  .replace(/{{business_name}}/g, body.client_name || 'our team')
  .replace(/{{service_interest}}/g, body.service_interest || 'your inquiry');

return [{ json: { ...body, message, touch_number: touch } }];
